// Appends Hair Removal ids 476-498 (23) + Facial Makeup ids 499-500 (2)
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const hrT=`"Hair Removal"`, hrTes=`"Depilación"`, hrPt=`"Hair Removal"`, hrPtes=`"Depilación"`
const fmT=`"Facial Makeup"`, fmTes=`"Maquillaje Facial"`, fmPt=`"Facial Makeup"`, fmPtes=`"Maquillaje Facial"`

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const HR = [
  { id: 476, question: "A client mentions that their skin tends to bruise easily and asks whether this is relevant to choosing a hair removal method. The most appropriate response is to:", question_es: "Un cliente menciona que su piel tiende a magullarse fácilmente y pregunta si esto es relevante para elegir un método de depilación. La respuesta más apropiada es:", options: ["Acknowledge that it can be relevant — methods involving more mechanical force or trauma to the skin (such as certain waxing techniques) may increase the likelihood of bruising in susceptible individuals, so a gentler method or modified technique might be considered", "Tell the client that bruising tendency has no possible relevance to any hair removal method", "Recommend the most forceful waxing technique available, since bruising is an unavoidable and unimportant side effect for everyone", "Refuse outright to discuss any aspect of the client's skin or health history before beginning the service"], correct: 0, options_es: ["Reconocer que puede ser relevante — los métodos que implican más fuerza mecánica o trauma a la piel (como ciertas técnicas de depilación con cera) pueden aumentar la probabilidad de moretones en personas susceptibles, por lo que se podría considerar un método más suave o una técnica modificada", "Decirle al cliente que la tendencia a magullarse no tiene ninguna relevancia posible para ningún método de depilación", "Recomendar la técnica de depilación con cera más enérgica disponible, ya que los moretones son un efecto secundario inevitable e sin importancia para todos", "Negarse rotundamente a discutir cualquier aspecto de la piel o el historial de salud del cliente antes de comenzar el servicio"], explanation: "Individuals who bruise easily may have heightened sensitivity to mechanical trauma, including the pulling and friction involved in some hair removal methods. Taking this information seriously and considering gentler alternatives or modified technique reflects attentive, individualized care — far more appropriate than dismissing the concern or using more forceful technique regardless of the client's described sensitivity." },
  { id: 477, question: "Which best describes why an esthetician should avoid double-dipping a wax applicator into a shared container of wax during a service?", question_es: "¿Cuál describe mejor por qué un esteticista debe evitar volver a sumergir un aplicador de cera en un recipiente compartido de cera durante un servicio?", options: ["Double-dipping can introduce bacteria, skin cells, and other contaminants from the client's skin into the shared product, creating a cross-contamination risk for that client and any future clients who use product from the same container", "Double-dipping is solely a matter of using more product than necessary and has no bearing on infection control", "Double-dipping makes the wax adhere to the hair more effectively and is therefore considered a recommended best practice", "Sharing a single container of wax among multiple clients poses no infection control concerns as long as the wax itself is heated"], correct: 0, options_es: ["Volver a sumergir el aplicador puede introducir bacterias, células de la piel y otros contaminantes de la piel del cliente en el producto compartido, creando un riesgo de contaminación cruzada para ese cliente y para cualquier cliente futuro que use producto del mismo recipiente", "Volver a sumergir el aplicador es simplemente una cuestión de usar más producto del necesario y no tiene relación con el control de infecciones", "Volver a sumergir el aplicador hace que la cera se adhiera al vello de manera más efectiva y, por lo tanto, se considera una práctica recomendada", "Compartir un solo recipiente de cera entre varios clientes no representa ninguna preocupación de control de infecciones siempre que la cera misma esté caliente"], explanation: "When an applicator that has touched a client's skin is placed back into a shared product container, it can transfer bacteria, skin cells, and other contaminants into that product — creating a cross-contamination risk for the current client (if product is reapplied) and for any future client who later uses product from that same container. Best practice is to use single-use applicators for each client and avoid double-dipping, in line with infection control principles." },
  { id: 478, question: "A returning waxing client mentions they have started a new prescription medication that increases photosensitivity. Which consideration is most relevant for the esthetician when planning today's service and aftercare guidance?", question_es: "Un cliente de depilación con cera que regresa menciona que ha comenzado un nuevo medicamento recetado que aumenta la fotosensibilidad. ¿Cuál consideración es más relevante para el esteticista al planificar el servicio y las indicaciones de cuidado posterior de hoy?", options: ["Photosensitizing medications can make skin more reactive and prone to irritation or sun-related damage, so the esthetician should consider gentler technique where appropriate and reinforce the importance of sun protection on treated areas afterward", "Photosensitizing medications have no relevance to waxing services and only matter for outdoor activities unrelated to esthetic treatments", "The esthetician should recommend the client stop taking the prescribed medication so that waxing can proceed without any special consideration", "Photosensitivity only matters for facial areas and has no bearing on services performed on other parts of the body"], correct: 0, options_es: ["Los medicamentos fotosensibilizantes pueden hacer que la piel sea más reactiva y propensa a la irritación o al daño relacionado con el sol, por lo que el esteticista debe considerar una técnica más suave cuando sea apropiado y reforzar la importancia de la protección solar en las áreas tratadas después", "Los medicamentos fotosensibilizantes no tienen relevancia para los servicios de depilación y solo importan para actividades al aire libre no relacionadas con los tratamientos estéticos", "El esteticista debe recomendar que el cliente deje de tomar el medicamento recetado para que la depilación pueda proceder sin ninguna consideración especial", "La fotosensibilidad solo importa para las áreas faciales y no tiene relación con los servicios realizados en otras partes del cuerpo"], explanation: "Photosensitizing medications can make skin more reactive overall and more vulnerable to sun-related irritation or damage — relevant both to how the skin may respond during the service and to aftercare guidance, since freshly treated skin is often more sensitive. The esthetician should take this information into account when selecting technique and should reinforce sun protection recommendations for the treated area, never advising a client to alter their prescribed medication regimen." },
  { id: 479, question: "Which best describes the appropriate use of pre-treatment numbing products (such as topical anesthetic creams) in a hair removal service?", question_es: "¿Cuál describe mejor el uso apropiado de productos adormecedores previos al tratamiento (como cremas anestésicas tópicas) en un servicio de depilación?", options: ["Following manufacturer instructions and any applicable regulations, confirming the product is appropriate for the client (no known allergies or contraindications), and using it only within the esthetician's authorized scope of practice — referring to or coordinating with appropriately licensed providers when a product or its use falls outside that scope", "Applying any available numbing product as heavily and frequently as desired, since these products carry no possible risk of reaction or complication", "Assuming numbing products are always within an esthetician's scope to recommend, supply, and apply regardless of the specific product or local regulations", "Using numbing products as a substitute for proper consultation, patch testing, and communication about what the client can expect"], correct: 0, options_es: ["Seguir las instrucciones del fabricante y cualquier regulación aplicable, confirmar que el producto es apropiado para el cliente (sin alergias o contraindicaciones conocidas), y usarlo solo dentro del alcance de práctica autorizado del esteticista — derivando o coordinando con proveedores con la licencia apropiada cuando un producto o su uso esté fuera de ese alcance", "Aplicar cualquier producto adormecedor disponible con la mayor frecuencia y cantidad posible, ya que estos productos no conllevan ningún riesgo posible de reacción o complicación", "Asumir que los productos adormecedores siempre están dentro del alcance de un esteticista para recomendar, suministrar y aplicar sin importar el producto específico o las regulaciones locales", "Usar productos adormecedores como sustituto de una consulta adecuada, prueba de parche y comunicación sobre lo que el cliente puede esperar"], explanation: "Topical anesthetic and numbing products carry their own considerations — including potential allergic reactions, interactions, and regulatory restrictions on who may recommend, supply, or apply them. An esthetician should only use such products within the boundaries of their license and applicable regulations, always screening for contraindications, and should never treat them as a substitute for proper consultation, testing, or clear communication about the procedure." },
  { id: 480, question: "A client asks why their esthetician recommends scheduling hair removal services at certain intervals (rather than whenever convenient) to achieve the smoothest ongoing results. The most accurate, appropriately scoped explanation is:", question_es: "Un cliente pregunta por qué su esteticista recomienda programar los servicios de depilación a ciertos intervalos (en lugar de cuando sea conveniente) para lograr los resultados más suaves de manera continua. La explicación más precisa y con el alcance apropiado es:", options: ["Hair grows in cycles, and timing services to align with where hair generally is in that growth cycle can support more consistent, even results over time, though the ideal interval can vary from person to person and area to area", "Scheduling intervals are based purely on the esthetician's calendar availability and have no connection to how hair grows or how the skin responds", "All hair on the body grows and regenerates at exactly the same identical rate for every individual, making timing irrelevant to outcomes", "Recommended intervals exist solely to increase the number of appointments scheduled and have no basis in how hair removal methods actually work"], correct: 0, options_es: ["El vello crece en ciclos, y programar los servicios para alinearlos con la etapa general del ciclo de crecimiento del vello puede favorecer resultados más consistentes y uniformes con el tiempo, aunque el intervalo ideal puede variar de una persona a otra y de un área a otra", "Los intervalos de programación se basan únicamente en la disponibilidad del calendario del esteticista y no tienen ninguna conexión con cómo crece el vello o cómo responde la piel", "Todo el vello del cuerpo crece y se regenera exactamente al mismo ritmo idéntico para cada individuo, lo que hace que el momento sea irrelevante para los resultados", "Los intervalos recomendados existen únicamente para aumentar el número de citas programadas y no tienen ninguna base en cómo funcionan realmente los métodos de depilación"], explanation: "Hair grows in natural cycles, and the visible result of root-based removal methods can be more even and longer-lasting when services are timed thoughtfully in relation to that cycle. Explaining this in simple, accurate terms — while acknowledging that the ideal interval varies by individual and treatment area — helps the client understand the reasoning behind a recommended schedule, rather than viewing it as arbitrary or solely calendar-driven." },
  { id: 481, question: "Which is the most appropriate way for an esthetician to respond if, partway through a waxing service, a client asks to stop because they are experiencing more discomfort than expected?", question_es: "¿Cuál es la forma más apropiada para que un esteticista responda si, a la mitad de un servicio de depilación con cera, un cliente le pide que se detenga porque está experimentando más molestias de lo esperado?", options: ["Respect the client's request, pause or stop the procedure as asked, check in about their comfort, and discuss options for how to proceed (including possibly modifying technique, switching methods, or ending the service for that day)", "Continue exactly as planned without acknowledging the request, since stopping partway through would be inconvenient", "Tell the client that stopping mid-service is never possible once a procedure has begun", "Increase the speed and intensity of the remaining procedure to finish as quickly as possible despite the client's request"], correct: 0, options_es: ["Respetar la solicitud del cliente, pausar o detener el procedimiento según lo solicitado, verificar su comodidad y discutir las opciones de cómo proceder (incluida la posibilidad de modificar la técnica, cambiar de método o finalizar el servicio por ese día)", "Continuar exactamente como se planeó sin reconocer la solicitud, ya que detenerse a mitad de camino sería inconveniente", "Decirle al cliente que detenerse a mitad del servicio nunca es posible una vez que un procedimiento ha comenzado", "Aumentar la velocidad y la intensidad del procedimiento restante para terminar lo más rápido posible a pesar de la solicitud del cliente"], explanation: "A client's comfort and consent matter throughout a service, not just at the start. If a client asks to pause or stop, the appropriate response is to respect that request immediately, check in with them, and collaboratively discuss how to proceed — whether that means adjusting technique, trying a different approach, or ending the session for that day. Ignoring the request, claiming it's impossible to stop, or rushing through against the client's wishes would be inappropriate and could damage trust and harm the client." },
  { id: 482, question: "Why might an esthetician recommend that a client avoid hot showers, saunas, swimming pools, or vigorous exercise for a period of time immediately following a waxing service?", question_es: "¿Por qué podría un esteticista recomendar que un cliente evite las duchas calientes, las saunas, las piscinas o el ejercicio vigoroso durante un período de tiempo inmediatamente después de un servicio de depilación con cera?", options: ["Freshly waxed skin has open follicles and can be more sensitive and reactive, so heat, friction, sweat, and exposure to pools or other shared water sources can increase irritation or the risk of introducing bacteria into the follicles", "These activities have no effect whatsoever on freshly waxed skin and are recommended to avoid purely as a matter of personal preference", "Avoiding these activities permanently prevents any future hair growth in the treated area", "These recommendations exist solely to extend the time the client spends thinking about their service rather than for any skin-related reason"], correct: 0, options_es: ["La piel recién depilada con cera tiene los folículos abiertos y puede ser más sensible y reactiva, por lo que el calor, la fricción, el sudor y la exposición a piscinas u otras fuentes de agua compartidas pueden aumentar la irritación o el riesgo de introducir bacterias en los folículos", "Estas actividades no tienen ningún efecto en la piel recién depilada con cera y se recomienda evitarlas únicamente como cuestión de preferencia personal", "Evitar estas actividades previene permanentemente cualquier futuro crecimiento del vello en el área tratada", "Estas recomendaciones existen únicamente para prolongar el tiempo que el cliente dedica a pensar en su servicio y no por ninguna razón relacionada con la piel"], explanation: "Immediately after waxing, hair follicles are temporarily open and the skin can be more sensitive and reactive. Heat (from showers or saunas), friction (from exercise), sweat, and exposure to shared water sources (like pools) can increase the likelihood of irritation or introduce bacteria into open follicles, potentially leading to discomfort or breakouts. Recommending a brief waiting period for these activities is a reasonable, evidence-informed aftercare guideline grounded in how freshly treated skin behaves." },
  { id: 483, question: "A client mentions that they have a history of keloid scarring and asks whether this affects which hair removal methods might be most suitable for them. The most appropriate response is to:", question_es: "Un cliente menciona que tiene antecedentes de cicatrices queloides y pregunta si esto afecta qué métodos de depilación podrían ser más adecuados para ellos. La respuesta más apropiada es:", options: ["Acknowledge that it can be relevant — methods or techniques that cause more trauma, irritation, or injury to the skin may carry a higher risk of triggering excess scar tissue formation in susceptible individuals, so gentler options and careful technique may be preferable", "Tell the client that keloid history has no possible relevance to any hair removal method or technique", "Recommend the most aggressive method available, since keloid-prone individuals are known to heal more efficiently than others", "Refuse to provide any hair removal service at all to any client who has ever experienced any type of scarring"], correct: 0, options_es: ["Reconocer que puede ser relevante — los métodos o técnicas que causan más trauma, irritación o lesión a la piel pueden conllevar un mayor riesgo de desencadenar la formación de tejido cicatricial excesivo en personas susceptibles, por lo que las opciones más suaves y una técnica cuidadosa pueden ser preferibles", "Decirle al cliente que el historial de queloides no tiene ninguna relevancia posible para ningún método o técnica de depilación", "Recomendar el método más agresivo disponible, ya que se sabe que las personas propensas a queloides cicatrizan de manera más eficiente que otras", "Negarse a brindar cualquier servicio de depilación a cualquier cliente que alguna vez haya experimentado algún tipo de cicatrización"], explanation: "Individuals prone to keloid scarring can develop excess scar tissue in response to relatively minor skin trauma, including irritation or injury that can occur with certain hair removal techniques. Acknowledging this relevance and favoring gentler methods and careful technique reflects sound, individualized professional judgment — rather than dismissing the history, intensifying the approach, or refusing service to anyone with any scarring history regardless of relevance." },
  { id: 484, question: "Which best describes appropriate communication between an esthetician and a client regarding setting realistic expectations for temporary hair removal methods (such as waxing, threading, or sugaring)?", question_es: "¿Cuál describe mejor la comunicación apropiada entre un esteticista y un cliente con respecto al establecimiento de expectativas realistas para los métodos de depilación temporal (como la cera, el hilo o el azucarado)?", options: ["Clearly explaining that these methods provide temporary results requiring ongoing maintenance, describing a general expected timeline for regrowth, and answering the client's questions honestly so they can plan accordingly", "Allowing the client to believe that any temporary hair removal method will produce permanent results lasting indefinitely", "Avoiding any discussion of how long results typically last so the client is not influenced by any expectations at all", "Promising the client a guaranteed, exact number of days before any regrowth will occur for their specific case"], correct: 0, options_es: ["Explicar claramente que estos métodos proporcionan resultados temporales que requieren mantenimiento continuo, describir una línea de tiempo general esperada para el recrecimiento, y responder las preguntas del cliente con honestidad para que puedan planificar en consecuencia", "Permitir que el cliente crea que cualquier método de depilación temporal producirá resultados permanentes que durarán indefinidamente", "Evitar cualquier discusión sobre cuánto tiempo suelen durar los resultados para que el cliente no se vea influenciado por ninguna expectativa", "Prometerle al cliente un número exacto y garantizado de días antes de que ocurra cualquier recrecimiento para su caso específico"], explanation: "Honest, clear communication about the temporary nature of these methods — including a general (not falsely precise) sense of how long smooth results commonly last and the need for ongoing maintenance — helps clients plan their routines and form realistic expectations. This transparency builds trust, in contrast to allowing misconceptions about permanence, withholding general information, or making guarantees that cannot reliably be kept for an individual." },
  { id: 485, question: "A client asks the esthetician why some areas of the body (such as the upper lip) seem to require more frequent hair removal appointments than other areas (such as the legs). An accurate, appropriately scoped explanation might note that:", question_es: "Un cliente le pregunta al esteticista por qué algunas áreas del cuerpo (como el labio superior) parecen requerir citas de depilación más frecuentes que otras áreas (como las piernas). Una explicación precisa y con el alcance apropiado podría señalar que:", options: ["Hair growth cycles and rates can vary by body area and by individual, so some areas may show visible regrowth sooner than others, which can influence how often a client may choose to schedule services for different areas", "Every area of the body has hair that grows and regenerates at exactly the same identical rate, so any difference the client notices must be incorrect", "Appointment frequency for different body areas is determined solely by the esthetician's preferences and has no connection to how hair grows in that area", "Hair on the face never regrows after any method of temporary hair removal, unlike hair on the legs"], correct: 0, options_es: ["Los ciclos y las tasas de crecimiento del vello pueden variar según el área del cuerpo y el individuo, por lo que algunas áreas pueden mostrar recrecimiento visible antes que otras, lo que puede influir en la frecuencia con la que un cliente elija programar servicios para diferentes áreas", "Cada área del cuerpo tiene vello que crece y se regenera exactamente a la misma tasa idéntica, por lo que cualquier diferencia que note el cliente debe ser incorrecta", "La frecuencia de las citas para diferentes áreas del cuerpo está determinada únicamente por las preferencias del esteticista y no tiene ninguna conexión con cómo crece el vello en esa área", "El vello del rostro nunca vuelve a crecer después de ningún método de depilación temporal, a diferencia del vello de las piernas"], explanation: "Hair growth rates and cycle lengths can differ across body areas and between individuals, which is why visible regrowth may become noticeable sooner in some areas than others. Sharing this general, accurate explanation helps the client understand why their recommended schedule might differ by area — supporting informed planning rather than assuming appointment timing is arbitrary or based solely on the esthetician's convenience." },
  { id: 486, question: "Which best describes a responsible approach for an esthetician when a client requests a hair removal service on an area where the esthetician notices signs that may indicate an active skin infection (such as visible pustules or unusual redness with warmth)?", question_es: "¿Cuál describe mejor un enfoque responsable para un esteticista cuando un cliente solicita un servicio de depilación en un área donde el esteticista nota signos que pueden indicar una infección cutánea activa (como pústulas visibles o enrojecimiento inusual con calor)?", options: ["Avoid performing the service on the affected area, explain the observation to the client respectfully, and recommend they have it evaluated by a healthcare provider before any hair removal is attempted there", "Proceed with the requested service exactly as planned, since visible skin changes have no bearing on whether hair removal can safely be performed", "Perform the service but apply extra wax or product directly over the affected area to help clear it up", "Refuse to discuss the observation with the client and proceed without any explanation of the change in plan"], correct: 0, options_es: ["Evitar realizar el servicio en el área afectada, explicarle la observación al cliente con respeto, y recomendar que lo haga evaluar por un proveedor de atención médica antes de intentar cualquier depilación allí", "Proceder con el servicio solicitado exactamente como se planeó, ya que los cambios visibles en la piel no tienen ninguna relación con si la depilación se puede realizar de manera segura", "Realizar el servicio pero aplicar cera o producto adicional directamente sobre el área afectada para ayudar a que se cure", "Negarse a discutir la observación con el cliente y proceder sin ninguna explicación sobre el cambio de plan"], explanation: "Signs suggestive of an active skin infection — such as pustules, unusual warmth, or spreading redness — represent a contraindication for hair removal on that area, since the procedure could worsen the condition, cause pain, or spread the infection. A responsible esthetician avoids the area, communicates the observation to the client clearly and respectfully, and recommends appropriate medical evaluation before attempting any service there." },
  { id: 487, question: "Which of the following best illustrates an esthetician appropriately managing a situation where a client's expectations about hair removal results conflict with what the chosen method can realistically achieve?", question_es: "¿Cuál de las siguientes ilustra mejor a un esteticista manejando apropiadamente una situación en la que las expectativas de un cliente sobre los resultados de la depilación entran en conflicto con lo que el método elegido puede lograr de manera realista?", options: ["Tactfully explaining what the chosen method can and cannot realistically achieve, discussing alternative options if appropriate, and helping the client make an informed decision based on accurate information", "Allowing the client to proceed with the service while privately believing their expectations cannot be met, without saying anything", "Telling the client their expectations are unreasonable without offering any further explanation or alternative options", "Promising the client that the chosen method will produce results that exceed what it can realistically achieve, in order to avoid an uncomfortable conversation"], correct: 0, options_es: ["Explicar con tacto lo que el método elegido puede y no puede lograr de manera realista, discutir opciones alternativas si es apropiado, y ayudar al cliente a tomar una decisión informada basada en información precisa", "Permitir que el cliente proceda con el servicio mientras cree en privado que sus expectativas no se pueden cumplir, sin decir nada", "Decirle al cliente que sus expectativas son irrazonables sin ofrecer ninguna explicación adicional ni opciones alternativas", "Prometerle al cliente que el método elegido producirá resultados que superan lo que puede lograr de manera realista, para evitar una conversación incómoda"], explanation: "When a gap exists between what a client expects and what a method can realistically deliver, the professional response is open, honest, and respectful communication — explaining realistic outcomes, exploring alternatives if relevant, and supporting the client in making an informed choice. This approach respects the client's autonomy and protects trust, unlike staying silent, being dismissive, or overpromising to avoid discomfort." },
  { id: 488, question: "Why is it considered good practice for an esthetician to document which hair removal method, products, and techniques were used during each client visit?", question_es: "¿Por qué se considera una buena práctica que un esteticista documente qué método, productos y técnicas de depilación se usaron durante cada visita del cliente?", options: ["Accurate records help the esthetician track what has worked well or poorly for that individual client over time, recall any reactions or sensitivities, and make more informed decisions for future visits — supporting safer and more consistent care", "Documentation is purely a formality required for billing purposes and has no connection to the quality or safety of future services", "Once a method is chosen for a client's first visit, it should never be reconsidered or adjusted at any future appointment", "Detailed records are unnecessary because an esthetician can be expected to remember every detail about every client from memory alone"], correct: 0, options_es: ["Los registros precisos ayudan al esteticista a rastrear qué ha funcionado bien o mal para ese cliente individual con el tiempo, recordar cualquier reacción o sensibilidad, y tomar decisiones más informadas para futuras visitas — apoyando una atención más segura y consistente", "La documentación es puramente una formalidad requerida para fines de facturación y no tiene ninguna conexión con la calidad o seguridad de los servicios futuros", "Una vez que se elige un método para la primera visita de un cliente, nunca debe reconsiderarse ni ajustarse en ninguna cita futura", "Los registros detallados son innecesarios porque se puede esperar que un esteticista recuerde cada detalle de cada cliente solo de memoria"], explanation: "Thorough documentation of methods, products, techniques, and any observed reactions creates a reliable record the esthetician can reference at future visits. This supports continuity of care, helps identify what approaches have worked well (or poorly) for that individual, reduces the risk of repeating problematic choices, and ultimately contributes to safer, more personalized, and more consistent service over time." },
  { id: 489, question: "A client asks the esthetician to explain, in simple terms, why waxing the same area repeatedly over time may sometimes lead to finer or sparser-looking regrowth for some individuals, while this is not guaranteed for everyone. An appropriately scoped response would note that:", question_es: "Un cliente le pide al esteticista que explique, en términos simples, por qué la depilación repetida con cera de la misma área a lo largo del tiempo a veces puede llevar a un recrecimiento más fino o más escaso en algunas personas, aunque esto no está garantizado para todos. Una respuesta con el alcance apropiado señalaría que:", options: ["Repeated removal from the root may, over time and for some individuals, be associated with finer or less noticeable regrowth in certain areas, but results vary significantly by person, area, and other factors, and this should not be promised as a guaranteed or permanent outcome", "Waxing the same area repeatedly always permanently destroys the hair follicle after a predictable, fixed number of sessions for every client", "There is no possible relationship between repeated waxing and the appearance of future hair regrowth for any individual", "Repeated waxing in the same area always causes hair to grow back thicker and darker than before, with no exceptions"], correct: 0, options_es: ["La eliminación repetida desde la raíz puede, con el tiempo y para algunas personas, estar asociada con un recrecimiento más fino o menos perceptible en ciertas áreas, pero los resultados varían significativamente según la persona, el área y otros factores, y esto no debe prometerse como un resultado garantizado o permanente", "Depilar repetidamente la misma área con cera siempre destruye permanentemente el folículo piloso después de un número predecible y fijo de sesiones para cada cliente", "No existe ninguna relación posible entre la depilación repetida con cera y la apariencia del futuro recrecimiento del vello para ningún individuo", "La depilación repetida en la misma área siempre hace que el vello vuelva a crecer más grueso y oscuro que antes, sin excepciones"], explanation: "Some individuals notice that hair appears finer or less dense in areas that have been repeatedly waxed over a long period, though this experience is not universal, predictable, or guaranteed, and waxing does not permanently destroy the follicle the way some other methods may. An honest explanation describes this as a possible, individually variable observation — never a promised or assured long-term outcome — helping the client form realistic expectations." },
  { id: 490, question: "Which best describes why an esthetician should ask about a client's recent use of self-tanning products before performing a hair removal service such as waxing?", question_es: "¿Cuál describe mejor por qué un esteticista debe preguntar sobre el uso reciente de productos autobronceadores de un cliente antes de realizar un servicio de depilación como la cera?", options: ["Hair removal methods that affect the surface of the skin (such as waxing) can lift or remove some of the self-tanner along with dead skin cells, potentially creating uneven color, so the esthetician may want to discuss timing and set realistic expectations", "Self-tanning products have no possible effect on how skin or its surface appearance responds to hair removal procedures", "Asking about self-tanner use is solely relevant to facial treatments and never applies to hair removal services", "Recent self-tanner application means the esthetician should select the most aggressive exfoliating hair removal method available"], correct: 0, options_es: ["Los métodos de depilación que afectan la superficie de la piel (como la cera) pueden levantar o eliminar parte del autobronceador junto con las células muertas de la piel, lo que podría crear un color desigual, por lo que el esteticista podría querer discutir el momento y establecer expectativas realistas", "Los productos autobronceadores no tienen ningún efecto posible en cómo responde la piel o su apariencia superficial a los procedimientos de depilación", "Preguntar sobre el uso de autobronceador solo es relevante para los tratamientos faciales y nunca se aplica a los servicios de depilación", "La aplicación reciente de autobronceador significa que el esteticista debe elegir el método de depilación exfoliante más agresivo disponible"], explanation: "Self-tanning products typically work by temporarily coloring the outermost layer of skin cells. Hair removal methods that lift away surface cells — such as waxing — can remove some of that color unevenly, potentially creating a patchy or streaky appearance. Asking about recent self-tanner use allows the esthetician to discuss timing considerations and set realistic expectations with the client about how the service might affect their current tan." },
  { id: 491, question: "A client asks the esthetician whether a particular at-home hair removal device they saw advertised online is safe and effective to use between professional appointments. The most appropriate response is to:", question_es: "Un cliente le pregunta al esteticista si un dispositivo de depilación para uso en casa que vio anunciado en línea es seguro y eficaz para usar entre citas profesionales. La respuesta más apropiada es:", options: ["Share an honest, professionally informed perspective based on available, credible information, note any general safety considerations the client should be aware of, and encourage them to review manufacturer guidance and consult additional reputable sources for product-specific questions", "Confidently endorse the product as completely safe and effective for every individual without reviewing any information about it", "Refuse to discuss any product the client did not purchase directly through the esthetician's own business", "Tell the client that any device advertised online must automatically be unsafe and should never be considered"], correct: 0, options_es: ["Compartir una perspectiva honesta e informada profesionalmente basada en información disponible y confiable, señalar cualquier consideración general de seguridad que el cliente deba conocer, y animarlo a revisar las indicaciones del fabricante y consultar fuentes adicionales confiables para preguntas específicas del producto", "Respaldar con confianza el producto como completamente seguro y eficaz para todas las personas sin revisar ninguna información sobre él", "Negarse a discutir cualquier producto que el cliente no haya comprado directamente a través del propio negocio del esteticista", "Decirle al cliente que cualquier dispositivo anunciado en línea debe ser automáticamente inseguro y nunca debe considerarse"], explanation: "Clients often want guidance about products they encounter outside the treatment room. A thoughtful esthetician offers a balanced, honest perspective grounded in available, credible information, flags general safety considerations (such as following manufacturer instructions and patch testing), and encourages the client to seek out reliable additional information — rather than blindly endorsing or condemning a product without basis, or refusing to engage with a reasonable question." },
  { id: 492, question: "Which best describes appropriate end-of-service communication for a hair removal appointment?", question_es: "¿Cuál describe mejor la comunicación apropiada al final de una cita de depilación?", options: ["Reviewing how the skin looks and feels immediately afterward, explaining appropriate aftercare steps (including sun protection and activities to avoid for a period of time), discussing a reasonable interval for the next appointment, and answering the client's questions honestly", "Avoiding any discussion of aftercare so the client must contact the business again to learn how to care for the treated area", "Pressuring the client to book the maximum number of future appointments regardless of their needs, preferences, or schedule", "Ending the appointment immediately with no further conversation once the physical procedure is finished"], correct: 0, options_es: ["Revisar cómo se ve y se siente la piel inmediatamente después, explicar los pasos de cuidado posterior apropiados (incluida la protección solar y las actividades que se deben evitar durante un período de tiempo), discutir un intervalo razonable para la próxima cita, y responder las preguntas del cliente con honestidad", "Evitar cualquier discusión sobre el cuidado posterior para que el cliente deba volver a contactar al negocio para aprender a cuidar el área tratada", "Presionar al cliente para que reserve la mayor cantidad posible de citas futuras sin importar sus necesidades, preferencias o horario", "Terminar la cita de inmediato sin ninguna conversación adicional una vez que finaliza el procedimiento físico"], explanation: "Thoughtful end-of-service communication reinforces good outcomes and client trust: reviewing the treated area, explaining clear aftercare guidance (including sun protection and activities to avoid temporarily), suggesting a reasonable follow-up interval based on the client's needs, and answering questions honestly — building a positive, informed relationship rather than withholding helpful information or applying pressure." },
  { id: 493, question: "Which of these best illustrates an esthetician maintaining proper sanitation and infection control specifically during a hair removal service?", question_es: "¿Cuál de estas ilustra mejor a un esteticista manteniendo el saneamiento y el control de infecciones adecuados específicamente durante un servicio de depilación?", options: ["Using clean, properly stored single-use applicators and supplies for each client, disinfecting reusable tools and surfaces according to protocol between clients, and following proper hand hygiene throughout the service", "Reusing applicators between different clients as long as they appear visibly clean to the eye", "Storing single-use items in an open, uncovered container that is easily accessible to anyone in the treatment room", "Disinfecting tools and surfaces only at the very end of each business day rather than between individual clients"], correct: 0, options_es: ["Usar aplicadores y suministros de un solo uso, limpios y correctamente almacenados, para cada cliente, desinfectar las herramientas y superficies reutilizables según el protocolo entre clientes, y seguir una higiene de manos adecuada durante todo el servicio", "Reutilizar los aplicadores entre diferentes clientes siempre que parezcan visiblemente limpios a la vista", "Almacenar los artículos de un solo uso en un recipiente abierto y descubierto que sea fácilmente accesible para cualquier persona en la sala de tratamiento", "Desinfectar las herramientas y superficies solo al final de cada día laboral en lugar de entre clientes individuales"], explanation: "Proper infection control during hair removal services includes using single-use applicators and supplies appropriately (never relying on visual inspection alone to judge cleanliness), disinfecting any reusable tools and surfaces according to established protocols between every client, practicing good hand hygiene, and storing supplies properly to avoid contamination — all essential, non-negotiable parts of providing safe services." },
  { id: 494, question: "A client mentions they have a history of fainting or feeling lightheaded during procedures involving discomfort. Which is the most appropriate way for the esthetician to incorporate this information into planning a hair removal service?", question_es: "Un cliente menciona que tiene antecedentes de desmayarse o sentirse mareado durante procedimientos que implican molestias. ¿Cuál es la forma más apropiada para que el esteticista incorpore esta información en la planificación de un servicio de depilación?", options: ["Acknowledge the information, consider practical accommodations (such as ensuring the client is comfortably positioned, well-hydrated, and not rushed, and checking in regularly throughout the service), and be prepared to pause or stop if the client shows signs of distress", "Disregard the information entirely, since fainting has no possible relevance to hair removal procedures", "Proceed at the fastest possible pace to minimize the total time the client spends feeling any discomfort", "Refuse to provide the requested service under any circumstances because of this reported history"], correct: 0, options_es: ["Reconocer la información, considerar adaptaciones prácticas (como asegurarse de que el cliente esté cómodamente posicionado, bien hidratado y no apurado, y verificar regularmente durante todo el servicio), y estar preparado para pausar o detenerse si el cliente muestra signos de malestar", "Ignorar la información por completo, ya que el desmayo no tiene ninguna relevancia posible para los procedimientos de depilación", "Proceder al ritmo más rápido posible para minimizar el tiempo total que el cliente pasa sintiendo cualquier malestar", "Negarse a brindar el servicio solicitado bajo cualquier circunstancia debido a este historial informado"], explanation: "A history of fainting or lightheadedness during uncomfortable procedures is meaningful information that calls for thoughtful accommodation rather than dismissal or refusal. Practical steps — comfortable positioning, ensuring the client isn't rushed or dehydrated, checking in frequently, and being ready to pause if needed — show attentive, individualized care and help reduce the likelihood of an adverse event during the service." },
  { id: 495, question: "Which best describes why an esthetician should avoid making definitive medical statements (such as diagnosing a skin condition or explaining a hormonal cause of excess hair growth) when a client asks about the underlying reason for their hair growth pattern?", question_es: "¿Cuál describe mejor por qué un esteticista debe evitar hacer afirmaciones médicas definitivas (como diagnosticar una condición de la piel o explicar una causa hormonal del crecimiento excesivo de vello) cuando un cliente pregunta sobre la razón subyacente de su patrón de crecimiento de vello?", options: ["Diagnosing medical causes of hair growth patterns requires medical training and evaluation that fall outside the scope of esthetic practice, and an inaccurate or unauthorized statement could mislead the client or delay them from seeking appropriate care", "Clients never have any genuine interest in understanding more about their own hair growth patterns", "Estheticians are fully qualified to diagnose any hormonal or medical condition related to hair growth without any additional training", "There is no possible harm in an esthetician offering a confident diagnosis of a medical condition during a consultation"], correct: 0, options_es: ["Diagnosticar las causas médicas de los patrones de crecimiento del vello requiere capacitación y evaluación médica que están fuera del alcance de la práctica estética, y una declaración inexacta o no autorizada podría confundir al cliente o retrasar que busque la atención apropiada", "Los clientes nunca tienen ningún interés genuino en entender más sobre sus propios patrones de crecimiento de vello", "Los esteticistas están completamente calificados para diagnosticar cualquier condición hormonal o médica relacionada con el crecimiento del vello sin ninguna capacitación adicional", "No existe ningún daño posible en que un esteticista ofrezca un diagnóstico seguro de una condición médica durante una consulta"], explanation: "Determining the underlying medical or hormonal cause of a hair growth pattern requires clinical evaluation that is outside an esthetician's scope of practice. Offering a confident diagnosis — even with good intentions — risks being inaccurate, could mislead the client, and might delay them from seeking appropriate medical evaluation for a condition that genuinely needs it. The appropriate response acknowledges the question respectfully and refers the client to a qualified healthcare provider for any medical-level explanation." },
  { id: 496, question: "Which of the following best illustrates an esthetician appropriately balancing efficiency with thoroughness when performing a hair removal service?", question_es: "¿Cuál de las siguientes ilustra mejor a un esteticista equilibrando apropiadamente la eficiencia con la minuciosidad al realizar un servicio de depilación?", options: ["Working at a steady, practiced pace that maintains proper technique, sanitation, and attentiveness to the client's comfort throughout — rather than sacrificing safety or quality simply to finish more quickly", "Working as quickly as absolutely possible at every step, even if it means skipping sanitation procedures or check-ins with the client", "Working as slowly as possible regardless of the client's schedule or the practical needs of the appointment", "Choosing to skip certain steps of the established procedure whenever the esthetician personally feels they are unnecessary that day"], correct: 0, options_es: ["Trabajar a un ritmo constante y experimentado que mantenga la técnica adecuada, el saneamiento y la atención a la comodidad del cliente durante todo el proceso — en lugar de sacrificar la seguridad o la calidad simplemente para terminar más rápido", "Trabajar lo más rápido absolutamente posible en cada paso, incluso si eso significa omitir los procedimientos de saneamiento o las verificaciones con el cliente", "Trabajar lo más lento posible sin importar el horario del cliente o las necesidades prácticas de la cita", "Elegir omitir ciertos pasos del procedimiento establecido cada vez que el esteticista personalmente sienta que son innecesarios ese día"], explanation: "Skilled professionals develop efficient, practiced techniques that allow them to work at a reasonable pace without compromising safety, sanitation, technique quality, or attentiveness to the client. True efficiency comes from proficiency and good preparation — not from skipping essential steps, rushing through client interactions, or, conversely, working unnecessarily slowly without regard for the practical needs of the appointment." },
  { id: 497, question: "A client asks the esthetician to explain, in general terms, what role the hair growth cycle (including phases of active growth and rest) plays in how visible results from temporary hair removal methods change over time. An accurate, appropriately scoped response would describe:", question_es: "Un cliente le pide al esteticista que explique, en términos generales, qué papel juega el ciclo de crecimiento del vello (incluidas las fases de crecimiento activo y reposo) en cómo cambian con el tiempo los resultados visibles de los métodos de depilación temporal. Una respuesta precisa y con el alcance apropiado describiría:", options: ["Hair goes through natural cycles of active growth and rest, and because not all hairs in an area are in the same phase at the same time, results from a single session may appear different — and may need to be repeated — as hairs in other phases become visible over subsequent weeks", "All the hairs in any given area of the body are always in the exact same phase of growth at the exact same time for every individual", "The hair growth cycle has no influence whatsoever on how results from temporary hair removal methods appear or change over time", "A single hair removal session permanently addresses every hair in an area regardless of what phase of growth each hair is in"], correct: 0, options_es: ["El vello pasa por ciclos naturales de crecimiento activo y reposo, y debido a que no todos los vellos de un área están en la misma fase al mismo tiempo, los resultados de una sola sesión pueden verse diferentes — y pueden necesitar repetirse — a medida que los vellos en otras fases se vuelven visibles en las semanas siguientes", "Todos los vellos en cualquier área dada del cuerpo siempre están exactamente en la misma fase de crecimiento al mismo tiempo para cada individuo", "El ciclo de crecimiento del vello no tiene ninguna influencia en cómo aparecen o cambian con el tiempo los resultados de los métodos de depilación temporal", "Una sola sesión de depilación aborda permanentemente cada vello en un área sin importar en qué fase de crecimiento se encuentre cada vello"], explanation: "Hair naturally cycles through phases of active growth and rest, and at any given time, the hairs in a particular area are typically in a mix of these phases. Because temporary removal methods primarily affect hairs that are visible and accessible at the time of the service, hairs that were in a resting phase may become noticeable later — which is part of why ongoing maintenance sessions are commonly recommended. Sharing this general concept in simple terms helps clients understand the pattern of regrowth they may observe." },
  { id: 498, question: "Which best summarizes the overall professional approach an esthetician should take when providing any hair removal service — from consultation through aftercare?", question_es: "¿Cuál resume mejor el enfoque profesional general que un esteticista debe adoptar al brindar cualquier servicio de depilación — desde la consulta hasta el cuidado posterior?", options: ["Gathering relevant information through thorough consultation, selecting an appropriate method and technique based on the client's individual needs and any contraindications, following proper sanitation and safety protocols throughout, communicating clearly and honestly at every step, and providing appropriate aftercare guidance afterward", "Choosing the same method and technique for every client regardless of their individual skin, hair, health history, or preferences", "Prioritizing speed above all other considerations so that as many appointments as possible can be completed each day", "Focusing primarily on encouraging the client to book the maximum possible number of future services, regardless of their needs or goals"], correct: 0, options_es: ["Reunir información relevante a través de una consulta exhaustiva, seleccionar un método y una técnica apropiados según las necesidades individuales del cliente y cualquier contraindicación, seguir los protocolos adecuados de saneamiento y seguridad durante todo el proceso, comunicarse de manera clara y honesta en cada paso, y proporcionar las indicaciones de cuidado posterior apropiadas después", "Elegir el mismo método y técnica para cada cliente sin importar su piel individual, vello, historial de salud o preferencias", "Priorizar la velocidad por encima de todas las demás consideraciones para poder completar tantas citas como sea posible cada día", "Enfocarse principalmente en alentar al cliente a reservar el mayor número posible de servicios futuros, sin importar sus necesidades u objetivos"], explanation: "A sound, professional approach to any hair removal service weaves together every stage: a thorough consultation that uncovers relevant individual factors, thoughtful selection of method and technique suited to that client (and free of contraindications), consistent adherence to sanitation and safety protocols, honest and clear communication throughout, and appropriate aftercare guidance at the end. This individualized, safety-and-trust-centered approach — not speed, uniformity, or sales — is what defines quality esthetic practice." },
]

const FM = [
  { id: 499, question: "What is the primary purpose of applying a color-correcting product (such as a green-tinted corrector for redness) before foundation in a facial makeup application?", question_es: "¿Cuál es el propósito principal de aplicar un producto corrector de color (como un corrector con tinte verde para el enrojecimiento) antes de la base de maquillaje en una aplicación de maquillaje facial?", options: ["To neutralize specific tones in the skin (such as redness) using complementary colors on the color wheel, creating a more even-looking base before foundation is applied", "To permanently change the client's natural skin tone for all future makeup applications", "To replace the need for foundation entirely in any complete makeup application", "To provide sun protection in place of a separate sunscreen product"], options_es: ["Neutralizar tonos específicos en la piel (como el enrojecimiento) utilizando colores complementarios en la rueda de colores, creando una base de aspecto más uniforme antes de aplicar la base de maquillaje", "Cambiar permanentemente el tono natural de la piel del cliente para todas las futuras aplicaciones de maquillaje", "Reemplazar por completo la necesidad de base de maquillaje en cualquier aplicación completa de maquillaje", "Proporcionar protección solar en lugar de un producto de protector solar separado"], correct: 0, explanation: "Color correction relies on the color wheel: colors opposite each other can neutralize one another when layered. A green-tinted corrector, for example, can help neutralize the appearance of redness because green and red sit opposite each other on the color wheel. Applied in a thin layer before foundation, this can create a more even-toned base — but it does not permanently alter skin tone, replace foundation, or substitute for sun protection." },
  { id: 500, question: "Which best describes an appropriate way to select a foundation shade and formula for a client during a makeup consultation?", question_es: "¿Cuál describe mejor una manera apropiada de seleccionar un tono y una fórmula de base de maquillaje para un cliente durante una consulta de maquillaje?", options: ["Testing options along the jawline in natural light, considering the client's undertone and skin type (such as oily, dry, or combination), and discussing the client's preferences for coverage and finish", "Selecting a shade based solely on the color of the bottle or packaging without testing it on the client's skin", "Choosing the same single shade and formula for every client regardless of their individual skin tone, undertone, or type", "Testing the product only on the back of the hand, since this area always perfectly matches facial skin tone for every client"], correct: 0, explanation: "Thoughtful foundation selection involves testing along the jawline (where the face meets the neck) in natural lighting to find the most accurate match, considering undertone (cool, warm, or neutral) as well as skin type, and discussing what the client wants in terms of coverage (light, medium, full) and finish (matte, dewy, natural). This individualized process produces a far more accurate, flattering, and long-wearing result than guessing from packaging or applying a one-size-fits-all approach." },
]

let out = readFileSync(FILE, 'utf8')
out += HR.map(q => fmt(q, hrT, hrTes, hrPt, hrPtes)).join('\n') + '\n'
out += '\n  // ─── FACIAL MAKEUP (ids 499–525) ────────────────────────────────────────────\n'
out += FM.map(q => fmt(q, fmT, fmTes, fmPt, fmPtes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${HR.length} Hair Removal (ids ${HR[0].id}–${HR[HR.length-1].id}) + ${FM.length} Facial Makeup (ids ${FM[0].id}–${FM[FM.length-1].id})`)
